-- Churches & Ministries expansion, Phase 5A: "The Bible in one year" and the church's own feature switches — PROPOSED, NOT APPLIED. FOR OWNER REVIEW ONLY.
--
-- The reading plan itself is NOT in the database: it is the same for every church and is generated by the application (src/lib/church/bibleYear/plan.ts: the 66 books in canonical order, 365 days,
-- scripture REFERENCES only, no Bible text). The database only keeps who started and which days they ticked, plus a small switch table for the church.
--
--   NEW  church_features              one row per church: bible_year, counselling, giving (all OFF by default). The church OWNER switches a feature on; the public reads the switches of a published
--                                     church page (so the page knows whether to show a section). No money setting lives here: giving is only a switch that a later phase reads.
--   NEW  bible_year_enrollments       a visitor who started the plan with a church: customer, church, start date (the Africa/Douala day they opted in, set by the DATABASE, never by the client),
--                                     ended_at when they leave. At most one open enrolment per visitor and church, at most 20 open per visitor.
--   NEW  bible_year_progress          the days a reader ticked (1..365). A day in the future cannot be ticked; a closed enrolment takes no more ticks.
--   NEW  functions church_features_guard(), bible_year_enrollment_guard(), bible_year_progress_guard() and their triggers.
--
-- PRIVACY: who reads the Bible with which church is private. The two reader tables have NO policy and NO privilege for any API role: only the service role reads or writes them, after the application has
-- verified the visitor's own cookie (the same design as the Bible programme enrolments of Phase 5). Church staff never see a reader; nothing here reaches analytics, push payloads or Ringo AI.
--
-- Nothing existing is changed: no existing column, constraint, policy, trigger or function is altered or replaced, and no row is read or written.
-- SELF-VERIFYING, one transaction: preconditions first, postconditions last. Any RAISE rolls everything back. Re-runnable.
--
-- Depends on: 2026-12-27_church_people_groups.sql, 2026-12-29_ministry_events_announcements.sql (ministry_today()), the customer tables (ringo_customers).
-- Preflight (read-only, run BEFORE): supabase/support/2027-01-07_church_bible_year.preflight.sql
-- Verify    (read-only, run AFTER):  supabase/support/2027-01-07_church_bible_year.verify.sql
-- Rollback: supabase/support/2027-01-07_church_bible_year.rollback.sql (refuses to run while any row exists unless the loss is explicitly confirmed).

begin;

set local lock_timeout = '5s';

-- ----------------------------------------------------------------------------
-- 0. PRECONDITIONS
-- ----------------------------------------------------------------------------
do $$
declare
  v_t text;
begin
  foreach v_t in array array['profiles', 'ringo_customers', 'users'] loop
    if to_regclass('public.' || v_t) is null then raise exception 'precondition failed: public.% does not exist', v_t; end if;
  end loop;
  foreach v_t in array array['is_church_profile(uuid)', 'church_is_owner(uuid)', 'is_admin()', 'ministry_today()'] loop
    if to_regprocedure('public.' || v_t) is null then raise exception 'precondition failed: function public.% is missing (apply the earlier church migrations first)', v_t; end if;
  end loop;
  if not exists (select 1 from pg_roles where rolname = 'anon') or not exists (select 1 from pg_roles where rolname = 'authenticated') or not exists (select 1 from pg_roles where rolname = 'service_role') then
    raise exception 'precondition failed: the database roles anon, authenticated and service_role must exist';
  end if;
  if (select count(*) from unnest(array['church_features', 'bible_year_enrollments', 'bible_year_progress']) t where to_regclass('public.' || t) is not null) not in (0, 3) then
    raise exception 'precondition failed: only some of this file''s tables exist (half-applied or foreign change)';
  end if;
  if exists (select 1 from pg_proc where pronamespace = 'public'::regnamespace and proname in ('church_features_guard', 'bible_year_enrollment_guard', 'bible_year_progress_guard')
               and coalesce(obj_description(oid, 'pg_proc'), '') <> 'managed by 2027-01-07_church_bible_year.sql') then
    raise exception 'precondition failed: a function named like one of this file''s exists and is not managed by it';
  end if;
end $$;

-- ----------------------------------------------------------------------------
-- 1. TABLES
-- ----------------------------------------------------------------------------
create table if not exists public.church_features (
  profile_id uuid primary key references public.profiles(id) on delete cascade,
  bible_year boolean not null default false,
  counselling boolean not null default false,
  giving boolean not null default false,
  updated_by uuid references public.users(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists public.bible_year_enrollments (
  id uuid primary key default gen_random_uuid(),
  customer_id uuid not null references public.ringo_customers(id) on delete cascade,
  profile_id uuid not null references public.profiles(id) on delete cascade,
  start_date date not null default public.ministry_today(),
  created_at timestamptz not null default now(),
  ended_at timestamptz,
  constraint bible_year_enrollments_dates_check check (start_date between date '2020-01-01' and date '2100-12-31')
);
create unique index if not exists bible_year_enrollments_open_key on public.bible_year_enrollments (customer_id, profile_id) where ended_at is null;
create index if not exists bible_year_enrollments_profile_idx on public.bible_year_enrollments (profile_id) where ended_at is null;

create table if not exists public.bible_year_progress (
  enrollment_id uuid not null references public.bible_year_enrollments(id) on delete cascade,
  day integer not null,
  done_at timestamptz not null default now(),
  primary key (enrollment_id, day),
  constraint bible_year_progress_day_check check (day between 1 and 365)
);

comment on table public.church_features is 'managed by 2027-01-07_church_bible_year.sql';
comment on table public.bible_year_enrollments is 'managed by 2027-01-07_church_bible_year.sql';
comment on table public.bible_year_progress is 'managed by 2027-01-07_church_bible_year.sql';

-- ----------------------------------------------------------------------------
-- 2. FUNCTIONS AND TRIGGERS
-- ----------------------------------------------------------------------------
create or replace function public.church_features_guard()
returns trigger
language plpgsql
security definer
set search_path = pg_catalog, public, pg_temp
as $$
begin
  if tg_op = 'INSERT' then
    if not public.is_church_profile(new.profile_id) then
      raise exception 'church_profile_required' using errcode = '23514', detail = 'switches can only be set for a profile with the Churches & Ministries category';
    end if;
    if auth.uid() is not null then new.updated_by := auth.uid(); end if;
  else
    if new.profile_id is distinct from old.profile_id then
      raise exception 'church_tenant_immutable' using errcode = '42501', detail = 'a row can never be moved to another church';
    end if;
    if auth.uid() is not null then new.updated_by := auth.uid(); end if;
    new.updated_at := now();
  end if;
  return new;
end;
$$;

-- An enrolment belongs to a church page; its start date is today's date in Cameroon, chosen here and never by the client; once written only ended_at can change; a visitor has at most 20 open ones.
create or replace function public.bible_year_enrollment_guard()
returns trigger
language plpgsql
security definer
set search_path = pg_catalog, public, pg_temp
as $$
begin
  if tg_op = 'INSERT' then
    if not public.is_church_profile(new.profile_id) then
      raise exception 'church_profile_required' using errcode = '23514', detail = 'the plan can only be followed with a Churches & Ministries page';
    end if;
    new.start_date := public.ministry_today();
    new.ended_at := null;
    if (select count(*) from public.bible_year_enrollments e where e.customer_id = new.customer_id and e.ended_at is null) >= 20 then
      raise exception 'bible_year_limit' using errcode = '23514', detail = 'too many open reading plans for this person';
    end if;
  else
    if new.customer_id is distinct from old.customer_id or new.profile_id is distinct from old.profile_id or new.start_date is distinct from old.start_date or new.created_at is distinct from old.created_at then
      raise exception 'bible_year_enrollment_immutable' using errcode = '23514', detail = 'only the end of a reading plan can change';
    end if;
    if old.ended_at is not null and new.ended_at is distinct from old.ended_at then
      raise exception 'bible_year_enrollment_immutable' using errcode = '23514', detail = 'a closed reading plan stays closed';
    end if;
  end if;
  return new;
end;
$$;

-- A day can be ticked only while the plan is open, and never before it has come (day n is reachable from the n-th calendar day on).
create or replace function public.bible_year_progress_guard()
returns trigger
language plpgsql
security definer
set search_path = pg_catalog, public, pg_temp
as $$
declare
  v_start date;
  v_ended timestamptz;
begin
  select e.start_date, e.ended_at into v_start, v_ended from public.bible_year_enrollments e where e.id = new.enrollment_id;
  if not found then
    raise exception 'bible_year_enrollment_missing' using errcode = '23503';
  end if;
  if v_ended is not null then
    raise exception 'bible_year_closed' using errcode = '23514', detail = 'this reading plan has ended';
  end if;
  if new.day > (public.ministry_today() - v_start) + 1 then
    raise exception 'bible_year_future_day' using errcode = '23514', detail = 'that day has not come yet';
  end if;
  return new;
end;
$$;

comment on function public.church_features_guard() is 'managed by 2027-01-07_church_bible_year.sql';
comment on function public.bible_year_enrollment_guard() is 'managed by 2027-01-07_church_bible_year.sql';
comment on function public.bible_year_progress_guard() is 'managed by 2027-01-07_church_bible_year.sql';
revoke all on function public.church_features_guard() from public, anon, authenticated;
revoke all on function public.bible_year_enrollment_guard() from public, anon, authenticated;
revoke all on function public.bible_year_progress_guard() from public, anon, authenticated;

drop trigger if exists church_features_guard_trg on public.church_features;
create trigger church_features_guard_trg before insert or update on public.church_features for each row execute function public.church_features_guard();
drop trigger if exists bible_year_enrollments_guard_trg on public.bible_year_enrollments;
create trigger bible_year_enrollments_guard_trg before insert or update on public.bible_year_enrollments for each row execute function public.bible_year_enrollment_guard();
drop trigger if exists bible_year_progress_guard_trg on public.bible_year_progress;
create trigger bible_year_progress_guard_trg before insert on public.bible_year_progress for each row execute function public.bible_year_progress_guard();
comment on trigger church_features_guard_trg on public.church_features is 'managed by 2027-01-07_church_bible_year.sql';
comment on trigger bible_year_enrollments_guard_trg on public.bible_year_enrollments is 'managed by 2027-01-07_church_bible_year.sql';
comment on trigger bible_year_progress_guard_trg on public.bible_year_progress is 'managed by 2027-01-07_church_bible_year.sql';

-- ----------------------------------------------------------------------------
-- 3. ROW-LEVEL SECURITY AND PRIVILEGES
-- ----------------------------------------------------------------------------
alter table public.church_features enable row level security;
alter table public.bible_year_enrollments enable row level security;
alter table public.bible_year_progress enable row level security;

revoke all on public.church_features, public.bible_year_enrollments, public.bible_year_progress from public, anon, authenticated;

-- church_features: the public reads the switches of a published church page; only the church OWNER writes them
grant select (profile_id, bible_year, counselling, giving, updated_at) on public.church_features to anon, authenticated;
grant insert (profile_id, bible_year, counselling, giving), update (bible_year, counselling, giving) on public.church_features to authenticated;
grant all on public.church_features to service_role;
-- the reader tables: the service role alone
grant all on public.bible_year_enrollments, public.bible_year_progress to service_role;

drop policy if exists church_features_public_select on public.church_features;
create policy church_features_public_select on public.church_features for select to anon, authenticated
  using (exists (select 1 from public.profiles p where p.id = profile_id and p.published = true));
drop policy if exists church_features_owner_select on public.church_features;
create policy church_features_owner_select on public.church_features for select to authenticated using (public.church_is_owner(profile_id));
drop policy if exists church_features_owner_insert on public.church_features;
create policy church_features_owner_insert on public.church_features for insert to authenticated with check (public.church_is_owner(profile_id));
drop policy if exists church_features_owner_update on public.church_features;
create policy church_features_owner_update on public.church_features for update to authenticated using (public.church_is_owner(profile_id)) with check (public.church_is_owner(profile_id));
drop policy if exists church_features_no_platform_admin on public.church_features;
create policy church_features_no_platform_admin on public.church_features as restrictive for all to authenticated
  using (not public.is_admin() or public.church_is_owner(profile_id)) with check (not public.is_admin() or public.church_is_owner(profile_id));

-- ----------------------------------------------------------------------------
-- 4. POSTCONDITIONS (any failure rolls the whole file back)
-- ----------------------------------------------------------------------------
do $$
declare
  v_t text;
begin
  foreach v_t in array array['church_features', 'bible_year_enrollments', 'bible_year_progress'] loop
    if not (select c.relrowsecurity from pg_class c where c.oid = ('public.' || v_t)::regclass) then raise exception 'postcondition failed: RLS is off on %', v_t; end if;
    if has_table_privilege('anon', 'public.' || v_t, 'insert') or has_table_privilege('anon', 'public.' || v_t, 'update') or has_table_privilege('anon', 'public.' || v_t, 'delete') or has_table_privilege('public', 'public.' || v_t, 'select') then
      raise exception 'postcondition failed: anon or PUBLIC has table-level rights on %', v_t;
    end if;
  end loop;
  foreach v_t in array array['bible_year_enrollments', 'bible_year_progress'] loop
    if has_table_privilege('anon', 'public.' || v_t, 'select') or has_table_privilege('authenticated', 'public.' || v_t, 'select') or has_table_privilege('authenticated', 'public.' || v_t, 'insert') then
      raise exception 'postcondition failed: an API role can reach the reader table %', v_t;
    end if;
    if exists (select 1 from pg_policy where polrelid = ('public.' || v_t)::regclass) then raise exception 'postcondition failed: the reader table % has a policy', v_t; end if;
  end loop;
  if has_column_privilege('anon', 'public.church_features', 'updated_by', 'select') then raise exception 'postcondition failed: anon can read updated_by'; end if;
  if (select count(*) from pg_trigger where not tgisinternal and tgname in ('church_features_guard_trg', 'bible_year_enrollments_guard_trg', 'bible_year_progress_guard_trg')) <> 3 then raise exception 'postcondition failed: triggers'; end if;
  foreach v_t in array array['church_features_guard()', 'bible_year_enrollment_guard()', 'bible_year_progress_guard()'] loop
    if has_function_privilege('anon', 'public.' || v_t, 'execute') or has_function_privilege('authenticated', 'public.' || v_t, 'execute') or has_function_privilege('public', 'public.' || v_t, 'execute') then
      raise exception 'postcondition failed: % is callable by an API role', v_t;
    end if;
  end loop;
end $$;

commit;
